const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { CloudNetworkRegistry, IamPolicyService } = require('../models/cloud');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/cloud.key'),
  cert: fs.readFileSync('/etc/ssl/cloud.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://cloud-console.internal');

  if (url.pathname === '/cloud/network-map') {
    const vpcId = url.searchParams.get('vpcId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Authentication required');
    }

    let user;
    try {
      user = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    // Verify user has IAM read permission on the target VPC
    const hasVpcAccess = await IamPolicyService.canReadVpc(user.accountId, vpcId);
    if (!hasVpcAccess) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: account not authorized for this VPC');
    }

    if (vpcId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/vpcs/${vpcId}/security-groups.json` }, async (err, pushStream) => {
        if (err) return;
        const topology = await CloudNetworkRegistry.getVpcTopology(vpcId);
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify(topology));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Network visualization frame loaded</body></html>');
  }
});

server.listen(8449);
